-- ISEXY help guides: staff-run help accounts that members find by area and
-- message for free (docs/GUIDES.md). Runs after 0016_ads.sql.
--
-- Who: 5 Admins (seats 1-5), one Director per region (Québec, 17) or
-- province (Cuba, 16), one District Manager per municipality or borough
-- (Québec 1,122 + 41, Cuba 168). A guide is answered by its operators (real
-- logins an admin assigns, isexy.guide_operators) and by every admin; each
-- reply keeps the real writer (guide_messages.author_user_id).
--
-- Ethics (owner discussion, non-negotiable): a guide is a staff help account
-- and never passes as a member.
--   - Guides are not rows of isexy.profiles and nothing here creates one:
--     they never appear in Discover, likes, matches, gifts or donations.
--   - Every member-facing read returns kind (admin | director |
--     district_manager), so the client always shows the staff badge.
--   - Messaging a guide is free: no allowance, credit, plan or payment check.
--   - No personal data: no age, birth date, gender or "looking for" field.
--
-- Access: the four tables are closed to anon and authenticated (no grants,
-- RLS on, no policies); everything goes through the SECURITY DEFINER RPCs.
--   A. guide_fold() (accent- and case-insensitive search) and the tables.
--   B. Internal helpers: the caller's access to a guide, message checks.
--   C. Public RPCs (anon + signed in): search_guides, get_guide. Public
--      fields of active guides only (never contact_email nor operators).
--   D. Member RPCs (signed in): start_guide_thread, send_guide_message,
--      list_my_guide_threads, get_guide_thread_messages,
--      mark_guide_thread_read. At most 20 member messages per 10 minutes
--      and 5 new threads per day. A suspended account (0015: profile
--      is_active false) cannot write.
--   E. Staff RPCs: my_guide_access, staff_guide_inbox,
--      staff_close_guide_thread. Answering as a guide: is_admin(), or an
--      operator of that guide whose account is not suspended (0015's
--      notion). Guide-side replies use send_guide_message and
--      get_guide_thread_messages.
--   F. Admin RPCs: staff_list_guides (with contact_email and operators),
--      staff_update_guide, staff_set_guide_operator,
--      staff_assign_operator_by_email.
--      Every staff write (edit, assign, unassign, reply, close) writes one
--      row of 0015's audit log isexy.staff_actions (log_staff_action).
--   G. Seed, generated by scripts/isexy/gen-guides-seed.py from
--      data/areas/*.csv, ON CONFLICT DO NOTHING: a re-run inserts nothing
--      and keeps the admins' edits.
--
-- isexy schema only. Idempotent without dropping anything: CREATE TABLE /
-- INDEX IF NOT EXISTS, CREATE OR REPLACE FUNCTION / TRIGGER, constraints
-- declared with their table. No row is deleted, here or by the RPCs: an
-- operator is unassigned with revoked_at, a thread is closed with status.
-- Every function is SECURITY DEFINER (guide_fold excepted: pure, no table)
-- with search_path pinned to isexy, extensions; REVOKE ALL FROM PUBLIC,
-- anon (and authenticated where members have no use for it), explicit GRANTs.
-- Tests: scripts/isexy/test/guides-smoke.sql.

-- =====================================================================
-- A1. guide_fold(): lowercase, Latin accents stripped (œ, æ, ß spelled
--     out), everything but a-z and 0-9 turned into single spaces.
--     "L'Île-Perrot" -> "l ile perrot". unaccent is an extension (database
--     wide, never created by ISEXY migrations), hence the translate table
--     (Latin-1 + Latin Extended-A, upper and lower case, so it works under
--     any lc_ctype).
-- =====================================================================
CREATE OR REPLACE FUNCTION isexy.guide_fold(p_text text)
RETURNS text
LANGUAGE sql
IMMUTABLE
PARALLEL SAFE
SET search_path = isexy, extensions
AS $$
  SELECT btrim(regexp_replace(
           lower(translate(
             replace(replace(replace(replace(replace(replace(coalesce(p_text, ''),
               'Œ', 'oe'), 'œ', 'oe'), 'Æ', 'ae'), 'æ', 'ae'), 'ß', 'ss'), 'ẞ', 'ss'),
             'ÀÁÂÃÄÅÇÈÉÊËÌÍÎÏÐÑÒÓÔÕÖØÙÚÛÜÝÞàáâãäåçèéêëìíîïðñòóôõöøùúûüýþÿĀāĂăĄąĆćĈĉĊċČčĎďĐđĒēĔĕĖėĘęĚěĜĝĞğĠġĢģĤĥĦħĨĩĪīĬĭĮįİıĴĵĶķĸĹĺĻļĽľĿŀŁłŃńŅņŇňŌōŎŏŐőŔŕŖŗŘřŚśŜŝŞşŠšŢţŤťŦŧŨũŪūŬŭŮůŰűŲųŴŵŶŷŸŹźŻżŽž',
             'aaaaaaceeeeiiiidnoooooouuuuytaaaaaaceeeeiiiidnoooooouuuuytyaaaaaaccccccccddddeeeeeeeeeegggggggghhhhiiiiiiiiiijjkkkllllllllllnnnnnnoooooorrrrrrssssssssttttttuuuuuuuuuuuuwwyyyzzzzzz')),
           '[^a-z0-9]+', ' ', 'g'))
$$;
REVOKE ALL ON FUNCTION isexy.guide_fold(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION isexy.guide_fold(text) TO service_role;

-- =====================================================================
-- A2. Tables
-- =====================================================================
-- One row per help account. Area guides are keyed by (country, area_kind,
-- area_slug); admins by seat. search_text = guide_fold(area name, the city of
-- a borough, parent name), set by the seed (area fields are not editable).
CREATE TABLE IF NOT EXISTS isexy.guides (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  kind text NOT NULL CHECK (kind IN ('admin', 'director', 'district_manager')),
  country text CHECK (country IN ('CA-QC', 'CU')),
  area_kind text CHECK (area_kind IN ('region', 'municipality', 'borough', 'province')),
  area_code text,
  area_slug text,
  area_name text,
  parent_name text,
  search_text text NOT NULL DEFAULT '',
  display_name text NOT NULL CHECK (char_length(btrim(display_name)) BETWEEN 1 AND 80),
  title text CHECK (title IS NULL OR char_length(title) BETWEEN 1 AND 80),
  bio text CHECK (bio IS NULL OR char_length(bio) BETWEEN 1 AND 1000),
  avatar_url text CHECK (avatar_url IS NULL OR (char_length(avatar_url) <= 500 AND avatar_url ~ '^https://[^[:space:]]+$')),
  contact_email text CHECK (contact_email IS NULL OR (char_length(contact_email) <= 254
                            AND contact_email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$')),
  active boolean NOT NULL DEFAULT true,
  seat integer CHECK (seat BETWEEN 1 AND 5),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT guides_area_key UNIQUE (country, area_kind, area_slug),
  CONSTRAINT guides_seat_key UNIQUE (seat),
  CONSTRAINT guides_kind_shape CHECK (
    (kind = 'admin' AND seat IS NOT NULL AND country IS NULL AND area_kind IS NULL AND area_code IS NULL
       AND area_slug IS NULL AND area_name IS NULL AND parent_name IS NULL)
    OR (kind = 'director' AND seat IS NULL AND area_slug IS NOT NULL AND area_name IS NOT NULL
       AND ((country = 'CA-QC' AND area_kind = 'region') OR (country = 'CU' AND area_kind = 'province')))
    OR (kind = 'district_manager' AND seat IS NULL AND area_slug IS NOT NULL AND area_name IS NOT NULL
       AND ((country = 'CA-QC' AND area_kind IN ('municipality', 'borough'))
            OR (country = 'CU' AND area_kind = 'municipality')))
  )
);
CREATE INDEX IF NOT EXISTS guides_kind_country_idx ON isexy.guides (kind, country);

CREATE OR REPLACE TRIGGER isexy_guides_updated_at
  BEFORE UPDATE ON isexy.guides
  FOR EACH ROW EXECUTE FUNCTION isexy.update_updated_at_column();

-- The real logins that may answer as a guide. Unassigning sets revoked_at
-- (the row and the audit log keep who had access, and when).
CREATE TABLE IF NOT EXISTS isexy.guide_operators (
  guide_id uuid NOT NULL REFERENCES isexy.guides(id),
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  assigned_by uuid,
  assigned_at timestamptz NOT NULL DEFAULT now(),
  revoked_by uuid,
  revoked_at timestamptz,
  PRIMARY KEY (guide_id, user_id)
);
CREATE INDEX IF NOT EXISTS guide_operators_user_idx ON isexy.guide_operators (user_id, guide_id)
  WHERE revoked_at IS NULL;

-- A member's conversation with a guide. One open thread per guide and
-- member; member_unread = guide replies the member has not read, guide_unread
-- = member messages the guide side has not read.
CREATE TABLE IF NOT EXISTS isexy.guide_threads (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  guide_id uuid NOT NULL REFERENCES isexy.guides(id),
  member_user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'closed')),
  created_at timestamptz NOT NULL DEFAULT now(),
  last_message_at timestamptz NOT NULL DEFAULT now(),
  member_unread integer NOT NULL DEFAULT 0 CHECK (member_unread >= 0),
  guide_unread integer NOT NULL DEFAULT 0 CHECK (guide_unread >= 0),
  closed_at timestamptz,
  closed_by uuid
);
CREATE UNIQUE INDEX IF NOT EXISTS guide_threads_one_open_idx ON isexy.guide_threads (guide_id, member_user_id)
  WHERE status = 'open';
CREATE INDEX IF NOT EXISTS guide_threads_member_idx ON isexy.guide_threads (member_user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS guide_threads_guide_idx ON isexy.guide_threads (guide_id, status, last_message_at DESC);
CREATE INDEX IF NOT EXISTS guide_threads_inbox_idx ON isexy.guide_threads (status, last_message_at DESC);

-- author_user_id is the real writer (the member, or the operator / admin who
-- answered as the guide), kept for accountability: no foreign key, so it
-- outlives a staff login.
CREATE TABLE IF NOT EXISTS isexy.guide_messages (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  thread_id uuid NOT NULL REFERENCES isexy.guide_threads(id) ON DELETE CASCADE,
  sender text NOT NULL CHECK (sender IN ('member', 'guide')),
  author_user_id uuid NOT NULL,
  body text NOT NULL CHECK (char_length(body) BETWEEN 1 AND 2000 AND body ~ '[^[:space:]]'),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS guide_messages_thread_idx ON isexy.guide_messages (thread_id, created_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS guide_messages_member_rate_idx ON isexy.guide_messages (author_user_id, created_at DESC)
  WHERE sender = 'member';

-- No direct access: RLS on with no policy, and no table privilege for the
-- client roles (the schema's default privileges grant them everything).
ALTER TABLE isexy.guides ENABLE ROW LEVEL SECURITY;
ALTER TABLE isexy.guide_operators ENABLE ROW LEVEL SECURITY;
ALTER TABLE isexy.guide_threads ENABLE ROW LEVEL SECURITY;
ALTER TABLE isexy.guide_messages ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON isexy.guides, isexy.guide_operators, isexy.guide_threads, isexy.guide_messages
  FROM PUBLIC, anon, authenticated;
GRANT ALL ON isexy.guides, isexy.guide_operators, isexy.guide_threads, isexy.guide_messages TO service_role;

-- =====================================================================
-- B. Internal helpers (never called by clients)
-- =====================================================================
-- 0015's suspension: the account keeps its rows but loses the staff tools
-- (and here, writing to guides). A guide login created by
-- isexy-staff-create-login has no profile: an admin unassigns it instead.
CREATE OR REPLACE FUNCTION isexy.guide_login_suspended(p_user_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
  SELECT EXISTS (SELECT 1 FROM isexy.profiles p WHERE p.user_id = p_user_id AND p.is_active IS FALSE)
$$;
REVOKE ALL ON FUNCTION isexy.guide_login_suspended(uuid) FROM PUBLIC, anon, authenticated;

-- How the caller may answer as this guide: 'admin', 'operator',
-- 'suspended' (an operator whose account is suspended) or NULL.
CREATE OR REPLACE FUNCTION isexy.guide_staff_access(p_guide_id uuid)
RETURNS text
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
  SELECT CASE
           WHEN auth.uid() IS NULL THEN NULL
           WHEN isexy.is_admin() THEN 'admin'
           WHEN NOT EXISTS (SELECT 1 FROM isexy.guide_operators o
                             WHERE o.guide_id = p_guide_id AND o.user_id = auth.uid() AND o.revoked_at IS NULL)
             THEN NULL
           WHEN isexy.guide_login_suspended(auth.uid()) THEN 'suspended'
           ELSE 'operator'
         END
$$;
REVOKE ALL ON FUNCTION isexy.guide_staff_access(uuid) FROM PUBLIC, anon, authenticated;

-- Message text: surrounding white space trimmed, 1 to 2000 characters.
CREATE OR REPLACE FUNCTION isexy.guide_clean_body(p_body text)
RETURNS text
LANGUAGE plpgsql
IMMUTABLE
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
DECLARE
  v text := regexp_replace(coalesce(p_body, ''), '^[[:space:]]+|[[:space:]]+$', '', 'g');
BEGIN
  IF v = '' OR char_length(v) > 2000 THEN
    RAISE EXCEPTION 'A message has 1 to 2000 characters' USING ERRCODE = '22023', HINT = 'guides.body_length';
  END IF;
  RETURN v;
END;
$$;
REVOKE ALL ON FUNCTION isexy.guide_clean_body(text) FROM PUBLIC, anon, authenticated;

-- At most 20 member messages to guides per 10 minutes (all threads).
-- Callers hold the member's advisory lock, so two calls cannot both pass.
CREATE OR REPLACE FUNCTION isexy.guide_check_message_rate(p_user_id uuid)
RETURNS void
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
BEGIN
  IF (SELECT count(*) FROM isexy.guide_messages m
       WHERE m.author_user_id = p_user_id AND m.sender = 'member'
         AND m.created_at > now() - interval '10 minutes') >= 20 THEN
    RAISE EXCEPTION 'At most 20 messages to guides every 10 minutes, please wait a little'
      USING ERRCODE = '54000', HINT = 'guides.rate_messages';
  END IF;
END;
$$;
REVOKE ALL ON FUNCTION isexy.guide_check_message_rate(uuid) FROM PUBLIC, anon, authenticated;

-- Assign (or unassign) an operator; the callers check is_admin(). Returns
-- whether anything changed; a change writes one audit row.
CREATE OR REPLACE FUNCTION isexy.guide_set_operator_core(
  p_guide_id uuid,
  p_user_id uuid,
  p_assign boolean,
  p_via text
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
DECLARE
  v_rows integer;
BEGIN
  IF p_assign IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'Say which login, and whether to assign or unassign it' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM isexy.guides g WHERE g.id = p_guide_id) THEN
    RAISE EXCEPTION 'Guide not found' USING ERRCODE = 'P0002', HINT = 'guides.guide_not_found';
  END IF;
  IF p_assign THEN
    IF NOT EXISTS (SELECT 1 FROM auth.users u WHERE u.id = p_user_id) THEN
      RAISE EXCEPTION 'No account with this id' USING ERRCODE = 'P0002', HINT = 'guides.user_not_found';
    END IF;
    VALUES (p_guide_id, p_user_id, auth.uid(), now())
    ON CONFLICT (guide_id, user_id) DO UPDATE
       SET assigned_by = excluded.assigned_by, assigned_at = excluded.assigned_at,
           revoked_by = NULL, revoked_at = NULL
     WHERE o.revoked_at IS NOT NULL;
  ELSE
    UPDATE isexy.guide_operators o
       SET revoked_by = auth.uid(), revoked_at = now()
     WHERE o.guide_id = p_guide_id AND o.user_id = p_user_id AND o.revoked_at IS NULL;
  END IF;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows > 0 THEN
    PERFORM isexy.log_staff_action(
      CASE WHEN p_assign THEN 'guide_assign_operator' ELSE 'guide_unassign_operator' END,
      NULL, p_guide_id, jsonb_build_object('guide_id', p_guide_id, 'user_id', p_user_id, 'via', p_via));
  END IF;
  RETURN v_rows > 0;
END;
$$;
REVOKE ALL ON FUNCTION isexy.guide_set_operator_core(uuid, uuid, boolean, text) FROM PUBLIC, anon, authenticated;

-- =====================================================================
-- C. Public RPCs (anon and signed in): active guides, public fields only
-- =====================================================================
-- Search by area: every word of p_query (accents, case and punctuation
-- ignored) must appear in the area, borough city, parent or display name.
-- Exact area name first, then names starting with the query, then admins,
-- directors, district managers. p_country: 'CA-QC' | 'CU' (admins have no
-- country: reach them with p_kind = 'admin'). total_count = all matches.
CREATE OR REPLACE FUNCTION isexy.search_guides(
  p_query text DEFAULT NULL,
  p_country text DEFAULT NULL,
  p_kind text DEFAULT NULL,
  p_limit integer DEFAULT 20,
  p_offset integer DEFAULT 0
)
RETURNS TABLE (
  id uuid, kind text, country text, area_kind text, area_name text, parent_name text,
  display_name text, title text, bio text, avatar_url text, total_count bigint
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
#variable_conflict use_column
DECLARE
  v_q text := isexy.guide_fold(left(p_query, 100));
  v_words text[];
BEGIN
  IF p_country IS NOT NULL AND p_country NOT IN ('CA-QC', 'CU') THEN
    RAISE EXCEPTION 'Unknown country (CA-QC or CU)' USING ERRCODE = '22023', HINT = 'guides.bad_country';
  END IF;
  IF p_kind IS NOT NULL AND p_kind NOT IN ('admin', 'director', 'district_manager') THEN
    RAISE EXCEPTION 'Unknown guide kind' USING ERRCODE = '22023', HINT = 'guides.bad_kind';
  END IF;
  v_words := CASE WHEN v_q = '' THEN ARRAY[]::text[] ELSE (string_to_array(v_q, ' '))[1:8] END;

  RETURN QUERY
    SELECT g.id, g.kind, g.country, g.area_kind, g.area_name, g.parent_name,
           g.display_name, g.title, g.bio, g.avatar_url, count(*) OVER ()
      FROM isexy.guides g
     WHERE g.active
       AND (p_country IS NULL OR g.country = p_country)
       AND (p_kind IS NULL OR g.kind = p_kind)
       AND NOT EXISTS (SELECT 1 FROM unnest(v_words) w(word)
                        WHERE strpos(g.search_text || ' ' || isexy.guide_fold(g.display_name), w.word) = 0)
     ORDER BY (v_q <> '' AND isexy.guide_fold(g.area_name) = v_q) DESC,
              (v_q <> '' AND isexy.guide_fold(g.area_name) LIKE v_q || '%') DESC,
              CASE g.kind WHEN 'admin' THEN 0 WHEN 'director' THEN 1 ELSE 2 END,
              g.country NULLS FIRST, g.area_name, g.seat, g.id
     LIMIT least(greatest(coalesce(p_limit, 20), 1), 100)
    OFFSET least(greatest(coalesce(p_offset, 0), 0), 100000);
END;
$$;
REVOKE ALL ON FUNCTION isexy.search_guides(text, text, text, integer, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION isexy.search_guides(text, text, text, integer, integer) TO anon, authenticated;

-- One active guide (no row when unknown or inactive).
CREATE OR REPLACE FUNCTION isexy.get_guide(p_guide_id uuid)
RETURNS TABLE (
  id uuid, kind text, country text, area_kind text, area_name text, parent_name text,
  display_name text, title text, bio text, avatar_url text
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
  SELECT g.id, g.kind, g.country, g.area_kind, g.area_name, g.parent_name,
         g.display_name, g.title, g.bio, g.avatar_url
    FROM isexy.guides g
   WHERE g.id = p_guide_id AND g.active
$$;
REVOKE ALL ON FUNCTION isexy.get_guide(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION isexy.get_guide(uuid) TO anon, authenticated;

-- =====================================================================
-- D. Member RPCs (signed in). Free: no allowance, credit, plan or payment.
-- =====================================================================
-- First message to a guide. Reuses the member's open thread with that
-- guide; a new thread counts towards 5 a day. Returns
-- {thread_id, message_id, reused, created_at}.
CREATE OR REPLACE FUNCTION isexy.start_guide_thread(p_guide_id uuid, p_body text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_body text;
  v_thread uuid;
  v_reused boolean := true;
  v_message uuid;
  v_at timestamptz;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sign in first' USING ERRCODE = '42501', HINT = 'guides.sign_in';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM isexy.guides g WHERE g.id = p_guide_id AND g.active) THEN
    RAISE EXCEPTION 'This guide is not available' USING ERRCODE = 'P0002', HINT = 'guides.guide_unavailable';
  END IF;
  IF isexy.guide_staff_access(p_guide_id) IS NOT NULL THEN
    RAISE EXCEPTION 'You answer for this guide: use the guide inbox' USING ERRCODE = '42501', HINT = 'guides.own_guide';
  END IF;
  IF isexy.guide_login_suspended(v_uid) THEN
    RAISE EXCEPTION 'This account is suspended' USING ERRCODE = '42501', HINT = 'guides.suspended';
  END IF;
  v_body := isexy.guide_clean_body(p_body);

  PERFORM pg_advisory_xact_lock(hashtextextended('isexy.guide_member:' || v_uid::text, 0));
  PERFORM isexy.guide_check_message_rate(v_uid);

  SELECT t.id INTO v_thread
    FROM isexy.guide_threads t
   WHERE t.guide_id = p_guide_id AND t.member_user_id = v_uid AND t.status = 'open'
   FOR UPDATE;
  v_at := clock_timestamp();
  IF v_thread IS NULL THEN
    IF (SELECT count(*) FROM isexy.guide_threads t
         WHERE t.member_user_id = v_uid AND t.created_at > now() - interval '1 day') >= 5 THEN
      RAISE EXCEPTION 'At most 5 new conversations with guides a day'
        USING ERRCODE = '54000', HINT = 'guides.rate_threads';
    END IF;
    VALUES (p_guide_id, v_uid, v_at, v_at)
    RETURNING id INTO v_thread;
    v_reused := false;
  END IF;

  VALUES (v_thread, 'member', v_uid, v_body, v_at)
  RETURNING id INTO v_message;
  UPDATE isexy.guide_threads t
     SET last_message_at = v_at, guide_unread = t.guide_unread + 1
   WHERE t.id = v_thread;

  RETURN jsonb_build_object('thread_id', v_thread, 'message_id', v_message, 'reused', v_reused, 'created_at', v_at);
END;
$$;
REVOKE ALL ON FUNCTION isexy.start_guide_thread(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION isexy.start_guide_thread(uuid, text) TO authenticated;

-- A message in an open thread. The thread's member writes as 'member'
-- (rate limited); an admin or an operator of the guide (not suspended)
-- writes as 'guide' (audit log). Returns {message_id, thread_id, sender,
-- created_at}.
CREATE OR REPLACE FUNCTION isexy.send_guide_message(p_thread_id uuid, p_body text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_thread isexy.guide_threads%ROWTYPE;
  v_access text;
  v_sender text;
  v_body text;
  v_message uuid;
  v_at timestamptz;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sign in first' USING ERRCODE = '42501', HINT = 'guides.sign_in';
  END IF;
  SELECT * INTO v_thread FROM isexy.guide_threads t WHERE t.id = p_thread_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Conversation not found' USING ERRCODE = 'P0002', HINT = 'guides.thread_not_found';
  END IF;

  IF v_thread.member_user_id = v_uid THEN
    v_sender := 'member';
    IF isexy.guide_login_suspended(v_uid) THEN
      RAISE EXCEPTION 'This account is suspended' USING ERRCODE = '42501', HINT = 'guides.suspended';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM isexy.guides g WHERE g.id = v_thread.guide_id AND g.active) THEN
      RAISE EXCEPTION 'This guide is not available' USING ERRCODE = 'P0002', HINT = 'guides.guide_unavailable';
    END IF;
  ELSE
    v_access := isexy.guide_staff_access(v_thread.guide_id);
    IF v_access = 'suspended' THEN
      RAISE EXCEPTION 'This account is suspended' USING ERRCODE = '42501', HINT = 'guides.suspended';
    ELSIF v_access IS NULL THEN
      RAISE EXCEPTION 'Not your conversation' USING ERRCODE = '42501', HINT = 'guides.not_allowed';
    END IF;
    v_sender := 'guide';
  END IF;
  v_body := isexy.guide_clean_body(p_body);

  IF v_sender = 'member' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('isexy.guide_member:' || v_uid::text, 0));
    PERFORM isexy.guide_check_message_rate(v_uid);
  END IF;
  SELECT * INTO v_thread FROM isexy.guide_threads t WHERE t.id = p_thread_id FOR UPDATE;
  IF v_thread.status <> 'open' THEN
    RAISE EXCEPTION 'This conversation is closed' USING ERRCODE = '55000', HINT = 'guides.thread_closed';
  END IF;

  v_at := clock_timestamp();
  VALUES (p_thread_id, v_sender, v_uid, v_body, v_at)
  RETURNING id INTO v_message;

  IF v_sender = 'member' THEN
    UPDATE isexy.guide_threads t
       SET last_message_at = v_at, guide_unread = t.guide_unread + 1
     WHERE t.id = p_thread_id;
  ELSE
    -- Answering reads the member's messages.
    UPDATE isexy.guide_threads t
       SET last_message_at = v_at, member_unread = t.member_unread + 1, guide_unread = 0
     WHERE t.id = p_thread_id;
    PERFORM isexy.log_staff_action('guide_reply', NULL, p_thread_id,
      jsonb_build_object('guide_id', v_thread.guide_id, 'message_id', v_message, 'as', v_access));
  END IF;

  RETURN jsonb_build_object('message_id', v_message, 'thread_id', p_thread_id, 'sender', v_sender, 'created_at', v_at);
END;
$$;
REVOKE ALL ON FUNCTION isexy.send_guide_message(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION isexy.send_guide_message(uuid, text) TO authenticated;

-- The member's threads, newest activity first (200 at most), with the
-- guide's public fields (kind: always show the staff badge). unread = guide
-- replies not read yet.
CREATE OR REPLACE FUNCTION isexy.list_my_guide_threads()
RETURNS TABLE (
  thread_id uuid, guide_id uuid, guide_kind text, guide_country text, guide_area_kind text,
  guide_area_name text, guide_parent_name text, guide_display_name text, guide_title text,
  guide_avatar_url text, guide_active boolean, status text, created_at timestamptz,
  last_message_at timestamptz, unread integer, last_message_sender text, last_message_preview text
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
  SELECT t.id, g.id, g.kind, g.country, g.area_kind,
         g.area_name, g.parent_name, g.display_name, g.title,
         g.avatar_url, g.active, t.status, t.created_at,
         t.last_message_at, t.member_unread, lm.sender, left(lm.body, 200)
    FROM isexy.guide_threads t
    JOIN isexy.guides g ON g.id = t.guide_id
    LEFT JOIN LATERAL (
      SELECT m.sender, m.body FROM isexy.guide_messages m
       WHERE m.thread_id = t.id
       ORDER BY m.created_at DESC, m.id DESC
       LIMIT 1
    ) lm ON true
   WHERE t.member_user_id = auth.uid()
   ORDER BY t.last_message_at DESC, t.id
   LIMIT 200
$$;
REVOKE ALL ON FUNCTION isexy.list_my_guide_threads() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION isexy.list_my_guide_threads() TO authenticated;

-- Messages of a thread, newest first: p_limit (1-200, default 50) messages
-- written before p_before (NULL = the latest). Pass the oldest created_at
-- received as p_before to load older ones. For the thread's member,
-- author_user_id is always NULL (who answered for the guide stays staff
-- information); for staff it is the real writer.
CREATE OR REPLACE FUNCTION isexy.get_guide_thread_messages(
  p_thread_id uuid,
  p_before timestamptz DEFAULT NULL,
  p_limit integer DEFAULT 50
)
RETURNS TABLE (
  id uuid, thread_id uuid, sender text, body text, created_at timestamptz,
  is_mine boolean, author_user_id uuid
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
#variable_conflict use_column
DECLARE
  v_uid uuid := auth.uid();
  v_guide uuid;
  v_member uuid;
  v_access text;
  v_staff boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sign in first' USING ERRCODE = '42501', HINT = 'guides.sign_in';
  END IF;
  SELECT t.guide_id, t.member_user_id INTO v_guide, v_member
    FROM isexy.guide_threads t WHERE t.id = p_thread_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Conversation not found' USING ERRCODE = 'P0002', HINT = 'guides.thread_not_found';
  END IF;
  IF v_member IS DISTINCT FROM v_uid THEN
    v_access := isexy.guide_staff_access(v_guide);
    IF v_access = 'suspended' THEN
      RAISE EXCEPTION 'This account is suspended' USING ERRCODE = '42501', HINT = 'guides.suspended';
    ELSIF v_access IS NULL THEN
      RAISE EXCEPTION 'Not your conversation' USING ERRCODE = '42501', HINT = 'guides.not_allowed';
    END IF;
    v_staff := true;
  END IF;

  RETURN QUERY
    SELECT m.id, m.thread_id, m.sender, m.body, m.created_at,
           (m.author_user_id = v_uid),
           CASE WHEN v_staff THEN m.author_user_id END
      FROM isexy.guide_messages m
     WHERE m.thread_id = p_thread_id
       AND (p_before IS NULL OR m.created_at < p_before)
     ORDER BY m.created_at DESC, m.id DESC
     LIMIT least(greatest(coalesce(p_limit, 50), 1), 200);
END;
$$;
REVOKE ALL ON FUNCTION isexy.get_guide_thread_messages(uuid, timestamptz, integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION isexy.get_guide_thread_messages(uuid, timestamptz, integer) TO authenticated;

-- The caller has read the thread: the member side (member_unread) or, for
-- staff who may answer as the guide, the guide side (guide_unread).
CREATE OR REPLACE FUNCTION isexy.mark_guide_thread_read(p_thread_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_guide uuid;
  v_member uuid;
  v_access text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sign in first' USING ERRCODE = '42501', HINT = 'guides.sign_in';
  END IF;
  SELECT t.guide_id, t.member_user_id INTO v_guide, v_member
    FROM isexy.guide_threads t WHERE t.id = p_thread_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Conversation not found' USING ERRCODE = 'P0002', HINT = 'guides.thread_not_found';
  END IF;
  IF v_member = v_uid THEN
    UPDATE isexy.guide_threads t SET member_unread = 0 WHERE t.id = p_thread_id AND t.member_unread <> 0;
    RETURN;
  END IF;
  v_access := isexy.guide_staff_access(v_guide);
  IF v_access = 'suspended' THEN
    RAISE EXCEPTION 'This account is suspended' USING ERRCODE = '42501', HINT = 'guides.suspended';
  ELSIF v_access IS NULL THEN
    RAISE EXCEPTION 'Not your conversation' USING ERRCODE = '42501', HINT = 'guides.not_allowed';
  END IF;
  UPDATE isexy.guide_threads t SET guide_unread = 0 WHERE t.id = p_thread_id AND t.guide_unread <> 0;
END;
$$;
REVOKE ALL ON FUNCTION isexy.mark_guide_thread_read(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION isexy.mark_guide_thread_read(uuid) TO authenticated;

-- =====================================================================
-- E. Staff RPCs (admins, and operators of a guide)
-- =====================================================================
-- What the caller may do with guides, for the console menu:
-- {is_admin, suspended, guides: [{id, kind, country, area_kind, area_name,
-- parent_name, display_name, active}]} (the guides they operate).
CREATE OR REPLACE FUNCTION isexy.my_guide_access()
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
  SELECT jsonb_build_object(
    'is_admin', coalesce(isexy.is_admin(), false),
    'suspended', coalesce(auth.uid() IS NOT NULL AND isexy.guide_login_suspended(auth.uid()), false),
    'guides', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'id', g.id, 'kind', g.kind, 'country', g.country, 'area_kind', g.area_kind,
               'area_name', g.area_name, 'parent_name', g.parent_name,
               'display_name', g.display_name, 'active', g.active)
             ORDER BY CASE g.kind WHEN 'admin' THEN 0 WHEN 'director' THEN 1 ELSE 2 END, g.area_name, g.seat)
        FROM isexy.guide_operators o
        JOIN isexy.guides g ON g.id = o.guide_id
       WHERE o.user_id = auth.uid() AND o.revoked_at IS NULL), '[]'::jsonb))
$$;
REVOKE ALL ON FUNCTION isexy.my_guide_access() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION isexy.my_guide_access() TO authenticated;

-- Threads the caller may answer: every thread for an admin, the threads of
-- their own guides for an operator (refused when suspended). p_status:
-- 'open' (default) | 'closed' | 'all' (or NULL). p_query matches the guide's
-- area / display name and the member's first name. Unread first, then the
-- latest activity. member_name = the member's ISEXY first name (NULL for an
-- account without a profile).
CREATE OR REPLACE FUNCTION isexy.staff_guide_inbox(
  p_status text DEFAULT 'open',
  p_query text DEFAULT NULL,
  p_limit integer DEFAULT 50,
  p_offset integer DEFAULT 0
)
RETURNS TABLE (
  thread_id uuid, guide_id uuid, guide_kind text, guide_country text, guide_area_kind text,
  guide_area_name text, guide_parent_name text, guide_display_name text, member_user_id uuid,
  member_name text, status text, created_at timestamptz, last_message_at timestamptz,
  guide_unread integer, member_unread integer, last_message_sender text, last_message_preview text,
  total_count bigint
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
#variable_conflict use_column
DECLARE
  v_uid uuid := auth.uid();
  v_admin boolean := coalesce(isexy.is_admin(), false);
  v_status text := nullif(coalesce(p_status, 'all'), 'all');
  v_q text := isexy.guide_fold(left(p_query, 100));
  v_words text[];
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sign in first' USING ERRCODE = '42501', HINT = 'guides.sign_in';
  END IF;
  IF NOT v_admin THEN
    IF NOT EXISTS (SELECT 1 FROM isexy.guide_operators o WHERE o.user_id = v_uid AND o.revoked_at IS NULL) THEN
      RAISE EXCEPTION 'Only ISEXY admins and guide operators have a guide inbox'
        USING ERRCODE = '42501', HINT = 'guides.not_allowed';
    END IF;
    IF isexy.guide_login_suspended(v_uid) THEN
      RAISE EXCEPTION 'This account is suspended' USING ERRCODE = '42501', HINT = 'guides.suspended';
    END IF;
  END IF;
  IF v_status IS NOT NULL AND v_status NOT IN ('open', 'closed') THEN
    RAISE EXCEPTION 'Unknown status (open, closed or all)' USING ERRCODE = '22023', HINT = 'guides.bad_status';
  END IF;
  v_words := CASE WHEN v_q = '' THEN ARRAY[]::text[] ELSE (string_to_array(v_q, ' '))[1:8] END;

  RETURN QUERY
    SELECT t.id, g.id, g.kind, g.country, g.area_kind,
           g.area_name, g.parent_name, g.display_name, t.member_user_id,
           p.first_name, t.status, t.created_at, t.last_message_at,
           t.guide_unread, t.member_unread, lm.sender, left(lm.body, 200),
           count(*) OVER ()
      FROM isexy.guide_threads t
      JOIN isexy.guides g ON g.id = t.guide_id
      LEFT JOIN isexy.profiles p ON p.user_id = t.member_user_id
      LEFT JOIN LATERAL (
        SELECT m.sender, m.body FROM isexy.guide_messages m
         WHERE m.thread_id = t.id
         ORDER BY m.created_at DESC, m.id DESC
         LIMIT 1
      ) lm ON true
     WHERE (v_admin OR EXISTS (SELECT 1 FROM isexy.guide_operators o
                                WHERE o.guide_id = t.guide_id AND o.user_id = v_uid AND o.revoked_at IS NULL))
       AND (v_status IS NULL OR t.status = v_status)
       AND NOT EXISTS (SELECT 1 FROM unnest(v_words) w(word)
                        WHERE strpos(g.search_text || ' ' || isexy.guide_fold(g.display_name) || ' '
                                     || isexy.guide_fold(p.first_name), w.word) = 0)
     ORDER BY (t.guide_unread > 0) DESC, t.last_message_at DESC, t.id
     LIMIT least(greatest(coalesce(p_limit, 50), 1), 200)
    OFFSET least(greatest(coalesce(p_offset, 0), 0), 100000);
END;
$$;
REVOKE ALL ON FUNCTION isexy.staff_guide_inbox(text, text, integer, integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION isexy.staff_guide_inbox(text, text, integer, integer) TO authenticated;

-- Close a thread (admin, or an operator of its guide). The member starts a
-- new thread to write again. Returns {thread_id, status, changed}.
CREATE OR REPLACE FUNCTION isexy.staff_close_guide_thread(p_thread_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
DECLARE
  v_thread isexy.guide_threads%ROWTYPE;
  v_access text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sign in first' USING ERRCODE = '42501', HINT = 'guides.sign_in';
  END IF;
  SELECT * INTO v_thread FROM isexy.guide_threads t WHERE t.id = p_thread_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Conversation not found' USING ERRCODE = 'P0002', HINT = 'guides.thread_not_found';
  END IF;
  v_access := isexy.guide_staff_access(v_thread.guide_id);
  IF v_access = 'suspended' THEN
    RAISE EXCEPTION 'This account is suspended' USING ERRCODE = '42501', HINT = 'guides.suspended';
  ELSIF v_access IS NULL THEN
    RAISE EXCEPTION 'Not your conversation' USING ERRCODE = '42501', HINT = 'guides.not_allowed';
  END IF;
  IF v_thread.status = 'closed' THEN
    RETURN jsonb_build_object('thread_id', p_thread_id, 'status', 'closed', 'changed', false);
  END IF;
  UPDATE isexy.guide_threads t
     SET status = 'closed', closed_at = now(), closed_by = auth.uid(), guide_unread = 0
   WHERE t.id = p_thread_id;
  PERFORM isexy.log_staff_action('guide_close_thread', NULL, p_thread_id,
    jsonb_build_object('guide_id', v_thread.guide_id, 'as', v_access));
  RETURN jsonb_build_object('thread_id', p_thread_id, 'status', 'closed', 'changed', true);
END;
$$;
REVOKE ALL ON FUNCTION isexy.staff_close_guide_thread(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION isexy.staff_close_guide_thread(uuid) TO authenticated;

-- =====================================================================
-- F. Admin RPCs (is_admin(): admin role, account not suspended)
-- =====================================================================
-- Every guide, active or not, with the staff-only fields: contact_email,
-- seat, area code / slug, operators [{user_id, email, assigned_at,
-- assigned_by, suspended}] (current ones), open_threads. Filters as
-- search_guides; p_query also matches contact_email.
CREATE OR REPLACE FUNCTION isexy.staff_list_guides(
  p_country text DEFAULT NULL,
  p_kind text DEFAULT NULL,
  p_query text DEFAULT NULL,
  p_limit integer DEFAULT 50,
  p_offset integer DEFAULT 0
)
RETURNS TABLE (
  id uuid, kind text, country text, area_kind text, area_code text, area_slug text,
  area_name text, parent_name text, display_name text, title text, bio text, avatar_url text,
  contact_email text, active boolean, seat integer, created_at timestamptz, updated_at timestamptz,
  operators jsonb, open_threads bigint, total_count bigint
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
#variable_conflict use_column
DECLARE
  v_q text := isexy.guide_fold(left(p_query, 100));
  v_words text[];
BEGIN
  IF NOT coalesce(isexy.is_admin(), false) THEN
    RAISE EXCEPTION 'Only ISEXY admins manage the guides' USING ERRCODE = '42501', HINT = 'guides.admin_only';
  END IF;
  IF p_country IS NOT NULL AND p_country NOT IN ('CA-QC', 'CU') THEN
    RAISE EXCEPTION 'Unknown country (CA-QC or CU)' USING ERRCODE = '22023', HINT = 'guides.bad_country';
  END IF;
  IF p_kind IS NOT NULL AND p_kind NOT IN ('admin', 'director', 'district_manager') THEN
    RAISE EXCEPTION 'Unknown guide kind' USING ERRCODE = '22023', HINT = 'guides.bad_kind';
  END IF;
  v_words := CASE WHEN v_q = '' THEN ARRAY[]::text[] ELSE (string_to_array(v_q, ' '))[1:8] END;

  RETURN QUERY
    SELECT g.id, g.kind, g.country, g.area_kind, g.area_code, g.area_slug,
           g.area_name, g.parent_name, g.display_name, g.title, g.bio, g.avatar_url,
           g.contact_email, g.active, g.seat, g.created_at, g.updated_at,
           coalesce((
             SELECT jsonb_agg(jsonb_build_object(
                      'user_id', o.user_id, 'email', u.email, 'assigned_at', o.assigned_at,
                      'assigned_by', o.assigned_by, 'suspended', isexy.guide_login_suspended(o.user_id))
                    ORDER BY o.assigned_at, o.user_id)
               FROM isexy.guide_operators o
               LEFT JOIN auth.users u ON u.id = o.user_id
              WHERE o.guide_id = g.id AND o.revoked_at IS NULL), '[]'::jsonb),
           (SELECT count(*) FROM isexy.guide_threads t WHERE t.guide_id = g.id AND t.status = 'open'),
           count(*) OVER ()
      FROM isexy.guides g
     WHERE (p_country IS NULL OR g.country = p_country)
       AND (p_kind IS NULL OR g.kind = p_kind)
       AND NOT EXISTS (SELECT 1 FROM unnest(v_words) w(word)
                        WHERE strpos(g.search_text || ' ' || isexy.guide_fold(g.display_name) || ' '
                                     || isexy.guide_fold(g.contact_email), w.word) = 0)
     ORDER BY (v_q <> '' AND isexy.guide_fold(g.area_name) = v_q) DESC,
              (v_q <> '' AND isexy.guide_fold(g.area_name) LIKE v_q || '%') DESC,
              CASE g.kind WHEN 'admin' THEN 0 WHEN 'director' THEN 1 ELSE 2 END,
              g.country NULLS FIRST, g.area_name, g.seat, g.id
     LIMIT least(greatest(coalesce(p_limit, 50), 1), 500)
    OFFSET least(greatest(coalesce(p_offset, 0), 0), 100000);
END;
$$;
REVOKE ALL ON FUNCTION isexy.staff_list_guides(text, text, text, integer, integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION isexy.staff_list_guides(text, text, text, integer, integer) TO authenticated;

-- Edit a guide's editable fields. NULL leaves a field as it is; '' clears
-- title, bio, avatar_url or contact_email (display_name cannot be empty).
-- Area fields, kind and seat are not editable. Returns {guide, changed}.
CREATE OR REPLACE FUNCTION isexy.staff_update_guide(
  p_guide_id uuid,
  p_display_name text DEFAULT NULL,
  p_title text DEFAULT NULL,
  p_bio text DEFAULT NULL,
  p_avatar_url text DEFAULT NULL,
  p_contact_email text DEFAULT NULL,
  p_active boolean DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
DECLARE
  v_old isexy.guides%ROWTYPE;
  v_new isexy.guides%ROWTYPE;
  v_changed text[] := ARRAY[]::text[];
  v_before jsonb := '{}'::jsonb;
  v_after jsonb := '{}'::jsonb;
  v_field text;
BEGIN
  IF NOT coalesce(isexy.is_admin(), false) THEN
    RAISE EXCEPTION 'Only ISEXY admins manage the guides' USING ERRCODE = '42501', HINT = 'guides.admin_only';
  END IF;
  SELECT * INTO v_old FROM isexy.guides g WHERE g.id = p_guide_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Guide not found' USING ERRCODE = 'P0002', HINT = 'guides.guide_not_found';
  END IF;
  v_new := v_old;

  IF p_display_name IS NOT NULL THEN
    v_new.display_name := btrim(p_display_name);
    IF char_length(v_new.display_name) NOT BETWEEN 1 AND 80 THEN
      RAISE EXCEPTION 'A display name has 1 to 80 characters' USING ERRCODE = '22023', HINT = 'guides.bad_display_name';
    END IF;
  END IF;
  IF p_title IS NOT NULL THEN
    v_new.title := nullif(btrim(p_title), '');
    IF char_length(v_new.title) > 80 THEN
      RAISE EXCEPTION 'A title has at most 80 characters' USING ERRCODE = '22023', HINT = 'guides.bad_title';
    END IF;
  END IF;
  IF p_bio IS NOT NULL THEN
    v_new.bio := nullif(btrim(p_bio), '');
    IF char_length(v_new.bio) > 1000 THEN
      RAISE EXCEPTION 'A bio has at most 1000 characters' USING ERRCODE = '22023', HINT = 'guides.bad_bio';
    END IF;
  END IF;
  IF p_avatar_url IS NOT NULL THEN
    v_new.avatar_url := nullif(btrim(p_avatar_url), '');
    IF v_new.avatar_url IS NOT NULL
       AND (char_length(v_new.avatar_url) > 500 OR v_new.avatar_url !~ '^https://[^[:space:]]+$') THEN
      RAISE EXCEPTION 'The picture must be an https:// address (500 characters at most)'
        USING ERRCODE = '22023', HINT = 'guides.bad_avatar_url';
    END IF;
  END IF;
  IF p_contact_email IS NOT NULL THEN
    v_new.contact_email := nullif(lower(btrim(p_contact_email)), '');
    IF v_new.contact_email IS NOT NULL
       AND (char_length(v_new.contact_email) > 254
            OR v_new.contact_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$') THEN
      RAISE EXCEPTION 'Not an e-mail address' USING ERRCODE = '22023', HINT = 'guides.bad_contact_email';
    END IF;
  END IF;
  IF p_active IS NOT NULL THEN
    v_new.active := p_active;
  END IF;

  FOREACH v_field IN ARRAY ARRAY['display_name', 'title', 'bio', 'avatar_url', 'contact_email', 'active'] LOOP
    IF (to_jsonb(v_old) -> v_field) IS DISTINCT FROM (to_jsonb(v_new) -> v_field) THEN
      v_changed := v_changed || v_field;
      v_before := v_before || jsonb_build_object(v_field, to_jsonb(v_old) -> v_field);
      v_after := v_after || jsonb_build_object(v_field, to_jsonb(v_new) -> v_field);
    END IF;
  END LOOP;

  IF cardinality(v_changed) > 0 THEN
    UPDATE isexy.guides g
       SET display_name = v_new.display_name, title = v_new.title, bio = v_new.bio,
           avatar_url = v_new.avatar_url, contact_email = v_new.contact_email, active = v_new.active
     WHERE g.id = p_guide_id
    RETURNING * INTO v_new;
    PERFORM isexy.log_staff_action('guide_update', NULL, p_guide_id,
      jsonb_build_object('changed', to_jsonb(v_changed), 'before', v_before, 'after', v_after));
  END IF;

  RETURN jsonb_build_object(
    'guide', jsonb_build_object(
      'id', v_new.id, 'kind', v_new.kind, 'country', v_new.country, 'area_kind', v_new.area_kind,
      'area_code', v_new.area_code, 'area_slug', v_new.area_slug, 'area_name', v_new.area_name,
      'parent_name', v_new.parent_name, 'display_name', v_new.display_name, 'title', v_new.title,
      'bio', v_new.bio, 'avatar_url', v_new.avatar_url, 'contact_email', v_new.contact_email,
      'active', v_new.active, 'seat', v_new.seat, 'updated_at', v_new.updated_at),
    'changed', to_jsonb(v_changed));
END;
$$;
REVOKE ALL ON FUNCTION isexy.staff_update_guide(uuid, text, text, text, text, text, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION isexy.staff_update_guide(uuid, text, text, text, text, text, boolean) TO authenticated;

-- Assign (p_assign true) or unassign (false) a login as an operator of a
-- guide. Idempotent. Returns {guide_id, user_id, assigned, changed}.
CREATE OR REPLACE FUNCTION isexy.staff_set_guide_operator(p_guide_id uuid, p_user_id uuid, p_assign boolean)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
DECLARE
  v_changed boolean;
BEGIN
  IF NOT coalesce(isexy.is_admin(), false) THEN
    RAISE EXCEPTION 'Only ISEXY admins manage the guides' USING ERRCODE = '42501', HINT = 'guides.admin_only';
  END IF;
  v_changed := isexy.guide_set_operator_core(p_guide_id, p_user_id, p_assign, 'user_id');
  RETURN jsonb_build_object('guide_id', p_guide_id, 'user_id', p_user_id, 'assigned', p_assign, 'changed', v_changed);
END;
$$;
REVOKE ALL ON FUNCTION isexy.staff_set_guide_operator(uuid, uuid, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION isexy.staff_set_guide_operator(uuid, uuid, boolean) TO authenticated;

-- Assign an existing account (looked up by its sign-in e-mail in auth.users)
-- as an operator of a guide: the path when isexy-staff-create-login answers
-- 409 (the e-mail already has an account). Returns {guide_id, user_id,
-- assigned, changed}.
CREATE OR REPLACE FUNCTION isexy.staff_assign_operator_by_email(p_guide_id uuid, p_email text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
DECLARE
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_users uuid[];
  v_changed boolean;
BEGIN
  IF NOT coalesce(isexy.is_admin(), false) THEN
    RAISE EXCEPTION 'Only ISEXY admins manage the guides' USING ERRCODE = '42501', HINT = 'guides.admin_only';
  END IF;
  IF v_email = '' OR strpos(v_email, '@') = 0 THEN
    RAISE EXCEPTION 'Not an e-mail address' USING ERRCODE = '22023', HINT = 'guides.bad_email';
  END IF;
  SELECT array_agg(u.id ORDER BY u.created_at) INTO v_users
    FROM auth.users u WHERE lower(u.email) = v_email;
  IF v_users IS NULL THEN
    RAISE EXCEPTION 'No account with this e-mail' USING ERRCODE = 'P0002', HINT = 'guides.user_not_found';
  ELSIF cardinality(v_users) > 1 THEN
    RAISE EXCEPTION 'Several accounts use this e-mail: assign by user id' USING ERRCODE = '22023', HINT = 'guides.email_ambiguous';
  END IF;
  v_changed := isexy.guide_set_operator_core(p_guide_id, v_users[1], true, 'email');
  RETURN jsonb_build_object('guide_id', p_guide_id, 'user_id', v_users[1], 'assigned', true, 'changed', v_changed);
END;
$$;
REVOKE ALL ON FUNCTION isexy.staff_assign_operator_by_email(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION isexy.staff_assign_operator_by_email(uuid, text) TO authenticated;

